16	pub fn handle(args: AddArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
17	    let runner = CliCommandRunner;
18	    let ws = load_workspace(global, &runner)?;
19	
20	    let mut entries = Vec::new();
21	    let mut summary = args.summary.clone();
22	
23	    if !args.packages.is_empty() {
24	        // Non-interactive mode (flags supplied via CLI or agent)
25	        for pkg_str in args.packages {
26	            let (name, sev_str) = pkg_str
27	                .rsplit_once(':')
28	                .ok_or_else(|| CliError::AddInvalidPackageSpec { spec: pkg_str.clone() })?;
29	
30	            let severity = parse_severity(sev_str)?;
31	
32	            // Resolves by any registered native name (not just a package's
33	            // primary/display name), reporting E102/E103 on a miss or
34	            // ecosystem-ambiguous bare name.
35	            callisto_graph::ConfigError::require_qualified(name, "--package")
36	                .map_err(callisto_graph::GraphError::Config)?;
37	            let resolved = ws.identity.resolve(name)?;
38	
39	            let package = resolved.display_name();
40	            if entries.iter().any(|e: &Entry| e.name == package) {
41	                return Err(CliError::AddDuplicatePackage {
42	                    package: name.to_owned(),
43	                });
44	            }
45	
46	            entries.push(Entry {
47	                // Use display_name() so "cargo/foo" is preserved, not just "foo".
48	                // In a polyglot workspace, the bare name is ambiguous across ecosystems.
49	                name: package,
50	                severity,
51	            });
52	        }
53	    } else if tty::is_interactive() {
54	        let all_packages = collect_package_names(ws.graph.packages());
55	        let Some((chosen, written)) = run_wizard(&all_packages, summary.clone(), &mut TerminalAddPrompter)? else {
56	            return Ok(ExitCode::SUCCESS);
57	        };
58	        entries = chosen;
59	        summary = Some(written);
60	    } else {
61	        return Err(CliError::NotATty);
62	    }
63	
64	    let raw_summary = summary.ok_or(CliError::AddSummaryRequired)?;
65	    let summary_text = validate_summary(&raw_summary)?;
66	    let changeset = Changeset {
67	        entries,
68	        summary: summary_text,
69	    };
70	    let text = callisto_model::format::write_changeset(&changeset)?;
71	
72	    let changeset_dir = ws.root.join(&ws.config.changesets_dir);
73	    let archive_dir = ws.root.join(ws.config.pre_archive_dir());
74	
75	    let Some(permit) = ApplyPermit::granted_unless_dry_run(global.dry_run) else {
76	        // Compute what WOULD be written, but never touch disk.
77	        let filename = unused_changeset_filename(&changeset_dir, &archive_dir)?;
78	        let rel_path = ws.config.changesets_dir.join(&filename).to_string_lossy().into_owned();
79	        match global.format {
80	            OutputFormat::Json => {
81	                let report = AddReport {
82	                    schema_version: SCHEMA_VERSION,
83	                    path: rel_path,
84	                    content: Some(text),
85	                    diagnostics: vec![],
86	                };
87	                emit_report(&mut std::io::stdout(), &report, true)?;
88	            }
89	            OutputFormat::Text => {
90	                emit_line(&format!(
91	                    "[DRY-RUN] Would add changeset: {rel_path} (no files written)\n\n{text}"
92	                ))?;
93	            }
94	        }
95	        return Ok(ExitCode::SUCCESS);
96	    };
97	
98	    fs::create_dir_all(&changeset_dir)?;
99	    let filename = create_changeset(&changeset_dir, &archive_dir, &text, &permit, generate_human_slug)?;
100	    let rel_path = ws.config.changesets_dir.join(&filename).to_string_lossy().into_owned();
101	
102	    match global.format {
103	        OutputFormat::Json => {
104	            let report = AddReport {
105	                schema_version: SCHEMA_VERSION,
106	                path: rel_path,
107	                content: None,
108	                diagnostics: vec![],
109	            };
110	            emit_report(&mut std::io::stdout(), &report, false)?;
111	        }
112	        OutputFormat::Text => {
113	            log_line(global.format, &format!("Added changeset: {rel_path}"))?;
114	        }
115	    }
116	
117	    Ok(ExitCode::SUCCESS)
118	}
