120	/// The wizard's questions; a scripted implementation drives tests.
121	trait AddPrompter {
122	    /// The indices the contributor ticked.
123	    fn multi_select(&mut self, items: &[String]) -> Result<Vec<usize>, CliError>;
124	    fn summary(&mut self) -> Result<String, CliError>;
125	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError>;
126	}
127	
128	struct TerminalAddPrompter;
129	
130	impl AddPrompter for TerminalAddPrompter {
131	    fn multi_select(&mut self, items: &[String]) -> Result<Vec<usize>, CliError> {
132	        Ok(MultiSelect::new().items(items).interact()?)
133	    }
134	
135	    fn summary(&mut self) -> Result<String, CliError> {
136	        Ok(Input::new()
137	            .validate_with(|input: &String| -> Result<(), &str> {
138	                if input.trim().is_empty() {
139	                    Err("Summary cannot be empty. Please enter a description of the change.")
140	                } else {
141	                    Ok(())
142	                }
143	            })
144	            .interact_text()?)
145	    }
146	
147	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError> {
148	        Ok(Confirm::new().with_prompt(prompt).default(default).interact()?)
149	    }
150	}
