152	/// The interactive five-step wizard (as in `@changesets/cli`): packages, which are major, which of the rest are minor
153	/// (the remainder default to patch), a summary unless one was given, then a preview to confirm. `None` when the
154	/// contributor declines the preview.
155	fn run_wizard(
156	    all_packages: &[String],
157	    summary: Option<String>,
158	    prompter: &mut impl AddPrompter,
159	) -> Result<Option<(Vec<Entry>, String)>, CliError> {
160	    if all_packages.is_empty() {
161	        return Err(CliError::AddNoPackagesInWorkspace);
162	    }
163	
164	    prompt_line("Which packages would you like to include in this changeset?");
165	    let selected_indices = prompter.multi_select(all_packages)?;
166	    if selected_indices.is_empty() {
167	        return Err(CliError::AddNoPackagesSelected);
168	    }
169	    let selected_packages: Vec<String> = selected_indices.into_iter().map(|i| all_packages[i].clone()).collect();
170	
171	    prompt_line("\nWhich of these packages should be a MAJOR bump?");
172	    prompt_line("(Select none if there are no breaking changes)");
173	    let major_set: std::collections::HashSet<usize> = prompter.multi_select(&selected_packages)?.into_iter().collect();
174	
175	    let minor_candidates: Vec<String> = selected_packages
176	        .iter()
177	        .enumerate()
178	        .filter(|(idx, _)| !major_set.contains(idx))
179	        .map(|(_, name)| name.clone())
180	        .collect();
181	    let minor_set: std::collections::HashSet<String> = if minor_candidates.is_empty() {
182	        std::collections::HashSet::new()
183	    } else {
184	        prompt_line("\nWhich of these packages should be a MINOR bump?");
185	        prompt_line("(Any remaining packages will default to a PATCH bump)");
186	        prompter
187	            .multi_select(&minor_candidates)?
188	            .into_iter()
189	            .map(|idx| minor_candidates[idx].clone())
190	            .collect()
191	    };
192	
193	    let entries: Vec<Entry> = selected_packages
194	        .iter()
195	        .enumerate()
196	        .map(|(idx, name)| Entry {
197	            name: name.clone(),
198	            severity: if major_set.contains(&idx) {
199	                Severity::Major
200	            } else if minor_set.contains(name) {
201	                Severity::Minor
202	            } else {
203	                Severity::Patch
204	            },
205	        })
206	        .collect();
207	
208	    let summary = match summary {
209	        Some(summary) => summary,
210	        None => {
211	            prompt_line("\nPlease enter a summary for this change:");
212	            prompter.summary()?
213	        }
214	    };
215	
216	    let preview = Changeset {
217	        entries: entries.clone(),
218	        summary: summary.clone(),
219	    };
220	    prompt_line(&format!(
221	        "\n=== Changeset Preview ===\n{}",
222	        callisto_model::format::write_changeset(&preview)?
223	    ));
224	    if !prompter.confirm("Is this your desired changeset?", true)? {
225	        prompt_line("Changeset creation cancelled.");
226	        return Ok(None);
227	    }
228	    Ok(Some((entries, summary)))
229	}
