231	/// Parses a CLI-supplied severity string, reporting every value `Severity`
232	/// actually accepts (`none`, `patch`, `minor`, `major`) on failure -- not a
233	/// stale subset that omits `none`.
234	fn parse_severity(sev_str: &str) -> Result<Severity, CliError> {
235	    sev_str.parse().map_err(|_err| CliError::InvalidSeverity {
236	        value: sev_str.to_string(),
237	    })
238	}
239	
240	/// Validates that a changeset summary string is non-empty and non-whitespace.
241	///
242	/// Returns `Ok(trimmed_summary)` on success, or a [`CliError`] with a user-facing message.
243	fn validate_summary(summary: &str) -> Result<String, CliError> {
244	    let trimmed = summary.trim().to_string();
245	    if trimmed.is_empty() {
246	        return Err(CliError::AddSummaryEmpty);
247	    }
248	    Ok(trimmed)
249	}
