251	/// Builds the list of package names shown in the interactive multiselect wizard.
252	///
253	/// Uses `.display_name()` so that packages sharing a bare name across different
254	/// ecosystems (e.g. `cargo/foo` and `npm/foo`) appear as distinct, qualified
255	/// entries in the list rather than two identical `"foo"` rows.
256	fn collect_package_names<'a>(packages: impl Iterator<Item = &'a callisto_model::Package>) -> Vec<String> {
257	    packages.map(|p| p.id.display_name()).collect()
258	}
