260	/// Writes `text` to a new file in `dir` named by `next_slug`, trying another slug whenever the name is taken, including
261	/// by a changeset another process created after this one looked. Nothing already in `dir` is ever replaced.
262	fn create_changeset(
263	    dir: &std::path::Path,
264	    archive: &std::path::Path,
265	    text: &str,
266	    permit: &ApplyPermit,
267	    mut next_slug: impl FnMut() -> String,
268	) -> Result<String, CliError> {
269	    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
270	    for _ in 0..64 {
271	        let filename = format!("{}.md", next_slug());
272	        if archived(archive, &filename)? {
273	            continue;
274	        }
275	        let path = dir.join(&filename);
276	        match callisto_model::atomic::atomic_write_new(&path, text, permit) {
277	            Ok(()) => return Ok(filename),
278	            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
279	            Err(source) => {
280	                return Err(CliError::Io {
281	                    source,
282	                    path: Some(path),
283	                })
284	            }
285	        }
286	    }
287	    Err(CliError::Io {
288	        source: std::io::Error::new(
289	            std::io::ErrorKind::AlreadyExists,
290	            "no unused changeset filename found after 64 attempts",
291	        ),
292	        path: Some(dir.to_path_buf()),
293	    })
294	}
295	
296	/// Whether a Changesets v3 pre cycle archived a note under `filename`; a new note there would read as its duplicate.
297	fn archived(archive: &std::path::Path, filename: &str) -> Result<bool, CliError> {
298	    let path = archive.join(filename);
299	    callisto_model::strict_fs::exists(&path).map_err(|source| CliError::Io {
300	        source,
301	        path: Some(path),
302	    })
303	}
304	
305	/// Picks a changeset filename that does not exist yet, so a slug collision never overwrites a pending changeset.
306	fn unused_changeset_filename(dir: &std::path::Path, archive: &std::path::Path) -> Result<String, CliError> {
307	    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
308	    for _ in 0..64 {
309	        let filename = format!("{}.md", generate_human_slug());
310	        let path = dir.join(&filename);
311	        let taken = callisto_model::strict_fs::exists(&path).map_err(|source| CliError::Io {
312	            source,
313	            path: Some(path.clone()),
314	        })?;
315	        if !taken && !archived(archive, &filename)? {
316	            return Ok(filename);
317	        }
318	    }
319	    Err(CliError::Io {
320	        source: std::io::Error::new(
321	            std::io::ErrorKind::AlreadyExists,
322	            "no unused changeset filename found after 64 attempts",
323	        ),
324	        path: Some(dir.to_path_buf()),
325	    })
326	}
