328	fn generate_human_slug() -> String {
329	    use std::sync::atomic::{AtomicU64, Ordering};
330	
331	    static COUNTER: AtomicU64 = AtomicU64::new(0);
332	
333	    let adjectives = [
334	        "swift", "clever", "bright", "silent", "brave", "calm", "eager", "gentle", "happy", "jolly", "keen", "lively",
335	        "mighty", "noble", "proud", "quick", "radiant", "sharp", "tough", "vivid",
336	    ];
337	    let nouns = [
338	        "foxes", "hawks", "wolves", "eagles", "bears", "lions", "otters", "pandas", "falcons", "tigers", "dolphins",
339	        "panthers", "cheetahs", "leopards", "ravens", "badgers", "lynxes", "cobras", "owls", "stags",
340	    ];
341	    let verbs = [
342	        "run", "fly", "leap", "soar", "dash", "hunt", "glide", "climb", "swim", "roar", "pounce", "sprint", "chase",
343	        "race", "bound", "drift", "jump", "strut", "spin", "surge",
344	    ];
345	
346	    // Each word list has 20 entries; consecutive counter values map to unique triples (a = idx % 20, n = (idx / 20) % 20,
347	    // v = (idx / 400) % 20), a bijection on 0..7999. A timestamp-derived offset varies the start across process restarts.
348	    let ts = std::time::SystemTime::now()
349	        .duration_since(std::time::UNIX_EPOCH)
350	        .map(|d| d.as_nanos() as u64)
351	        .unwrap_or(0);
352	
353	    let count = COUNTER.fetch_add(1, Ordering::Relaxed);
354	    // Shift ts right to get a slowly-varying cross-run offset (changes every ~1 µs).
355	    let offset = (ts >> 10) % 8000;
356	    let idx = (count + offset) % 8000;
357	
358	    let a = adjectives[(idx % 20) as usize];
359	    let n = nouns[((idx / 20) % 20) as usize];
360	    let v = verbs[((idx / 400) % 20) as usize];
361	
362	    format!("{a}-{n}-{v}")
363	}
