372	    /// Answers the wizard from a script: each multi-select, then the summary, then the confirmation.
373	    #[derive(Default)]
374	    struct Scripted {
375	        selections: std::collections::VecDeque<Vec<usize>>,
376	        summary: Option<String>,
377	        confirm: bool,
378	        /// The items each multi-select was shown, in order.
379	        shown: Vec<Vec<String>>,
380	        summary_asked: bool,
381	    }
382	
383	    impl AddPrompter for Scripted {
384	        fn multi_select(&mut self, items: &[String]) -> Result<Vec<usize>, CliError> {
385	            self.shown.push(items.to_vec());
386	            Ok(self.selections.pop_front().expect("an unexpected multi-select"))
387	        }
388	
389	        fn summary(&mut self) -> Result<String, CliError> {
390	            self.summary_asked = true;
391	            Ok(self.summary.clone().expect("an unexpected summary prompt"))
392	        }
393	
394	        fn confirm(&mut self, _prompt: &str, _default: bool) -> Result<bool, CliError> {
395	            Ok(self.confirm)
396	        }
397	    }
398	
399	    fn names(names: &[&str]) -> Vec<String> {
400	        names.iter().map(|name| (*name).to_owned()).collect()
401	    }
402	
403	    fn severities(entries: &[Entry]) -> Vec<(&str, Severity)> {
404	        entries
405	            .iter()
406	            .map(|entry| (entry.name.as_str(), entry.severity))
407	            .collect()
408	    }
