410	    #[test]
411	    fn the_wizard_gives_majors_then_minors_and_defaults_the_rest_to_patch() {
412	        let mut prompter = Scripted {
413	            selections: [vec![0, 1, 2], vec![0], vec![0]].into(),
414	            summary: Some("Rework the API".to_owned()),
415	            confirm: true,
416	            ..Default::default()
417	        };
418	        let (entries, summary) = run_wizard(&names(&["cargo/a", "cargo/b", "cargo/c"]), None, &mut prompter)
419	            .unwrap()
420	            .expect("confirmed");
421	        assert_eq!(
422	            severities(&entries),
423	            [
424	                ("cargo/a", Severity::Major),
425	                ("cargo/b", Severity::Minor),
426	                ("cargo/c", Severity::Patch)
427	            ]
428	        );
429	        assert_eq!(summary, "Rework the API");
430	        // The minor question is only about the packages that are not already major.
431	        assert_eq!(prompter.shown[2], names(&["cargo/b", "cargo/c"]));
432	    }
