new='''/// A package the wizard offers, and whether it changed since its last tag.
struct Choice {
    name: String,
    changed: bool,
}

/// The interactive five-step wizard (as in `@changesets/cli`): packages, which are major, which of the rest are minor
/// (the remainder default to patch), a summary unless one was given, then a preview to confirm. Changed packages are
/// listed first and start ticked. `None` when the contributor declines the preview.
fn run_wizard(
    choices: &[Choice],
    summary: Option<String>,
    prompter: &mut impl AddPrompter,
) -> Result<Option<(Vec<Entry>, String)>, CliError> {
    if choices.is_empty() {
        return Err(CliError::AddNoPackagesInWorkspace);
    }

    let mut ordered: Vec<&Choice> = choices.iter().collect();
    ordered.sort_by_key(|choice| !choice.changed);
    let labels: Vec<String> = ordered
        .iter()
        .map(|choice| {
            if choice.changed {
                format!("{} (changed)", choice.name)
            } else {
                choice.name.clone()
            }
        })
        .collect();
    let checked: Vec<bool> = ordered.iter().map(|choice| choice.changed).collect();
    let selected_indices = prompter.multi_select(
        "Which packages does this change affect? (Space toggles, Enter confirms)",
        &labels,
        &checked,
    )?;
    if selected_indices.is_empty() {
        return Err(CliError::AddNoPackagesSelected);
    }
    let selected_packages: Vec<String> = selected_indices.into_iter().map(|i| ordered[i].name.clone()).collect();
    let unticked = vec![false; selected_packages.len()];

    let major_set: std::collections::HashSet<usize> = prompter
        .multi_select(
            "Which of these are a MAJOR bump? (none unless the change breaks users)",
            &selected_packages,
            &unticked,
        )?
        .into_iter()
        .collect();

    let minor_candidates: Vec<String> = selected_packages
        .iter()
        .enumerate()
        .filter(|(idx, _)| !major_set.contains(idx))
        .map(|(_, name)| name.clone())
        .collect();
    let minor_set: std::collections::HashSet<String> = if minor_candidates.is_empty() {
        std::collections::HashSet::new()
    } else {
        prompter
            .multi_select(
                "Which of these are a MINOR bump? (the rest get a PATCH bump)",
                &minor_candidates,
                &unticked[..minor_candidates.len()],
            )?
            .into_iter()
            .map(|idx| minor_candidates[idx].clone())
            .collect()
    };

    let entries: Vec<Entry> = selected_packages
        .iter()
        .enumerate()
        .map(|(idx, name)| Entry {
            name: name.clone(),
            severity: if major_set.contains(&idx) {
                Severity::Major
            } else if minor_set.contains(name) {
                Severity::Minor
            } else {
                Severity::Patch
            },
        })
        .collect();

    let summary = match summary {
        Some(summary) => summary,
        None => prompter.summary("Summary for the changelog")?,
    };

    let preview = Changeset {
        entries: entries.clone(),
        summary: summary.clone(),
    };
    prompt_line(&format!(
        "\\n=== Changeset Preview ===\\n{}",
        callisto_model::format::write_changeset(&preview)?
    ));
    if !prompter.confirm("Is this your desired changeset?", true)? {
        prompt_line("Changeset creation cancelled.");
        return Ok(None);
    }
    Ok(Some((entries, summary)))
}

