/// Rows a package list shows before it pages.
const PAGE: usize = 15;

struct TerminalAddPrompter {
    theme: ColorfulTheme,
}

impl AddPrompter for TerminalAddPrompter {
    fn multi_select(
        &mut self,
        prompt: &str,
